#!/usr/bin/env python3
"""Copy Breathe into the site repo, stamping a provenance header on the page.

    sync_breathe.py <source dir> <destination dir> <sha> [date]

Breathe ships as two files: the page, which gets the header, and fonts.css,
which is copied byte for byte because it is a generated bundle. Both must land
together, since the page loads the stylesheet from beside itself.

Comparison ignores the header, so a re-run on an unchanged app reports no change
rather than manufacturing a commit whose only difference is today's date.

Prints `changed=true|false` to $GITHUB_OUTPUT when running under Actions.
"""
import datetime
import io
import os
import shutil
import sys

DOCTYPE = "<!doctype html>"

PAGE = "index.html"
VERBATIM = ["fonts.css"]

HEADER = """<!doctype html>
<!--
  Breathe — a guided breathing pacer: coherence, box, and the Wim Hof method.
  Two-file copy: this page plus fonts.css, which must sit beside it.

  Synced {date} from github.com/arnaudin/breathe @ {sha}, by that repo's
  .github/workflows/sync-to-site.yml. Do not edit this file: edit the source and
  the next push overwrites this copy.

  No front matter, so Jekyll passes it through untouched. No build, no
  dependencies, and no network requests at all — the typefaces are embedded
  in fonts.css as data URIs.
-->"""


def body_of(text):
    """The document after any leading doctype and provenance comment."""
    if not text.startswith(DOCTYPE):
        return text
    rest = text[len(DOCTYPE):]
    if rest.lstrip().startswith("<!--"):
        end = rest.find("-->")
        if end != -1:
            return rest[end + 3:]
    return rest


def read(path):
    try:
        return io.open(path, "rb").read()
    except IOError:
        return None


def main():
    if len(sys.argv) not in (4, 5):
        sys.exit(__doc__)
    src_dir, dst_dir, sha = sys.argv[1:4]
    date = sys.argv[4] if len(sys.argv) == 5 else datetime.date.today().isoformat()

    src_page = os.path.join(src_dir, PAGE)
    source = io.open(src_page, encoding="utf-8").read()
    if not source.startswith(DOCTYPE):
        sys.exit("refusing to sync: %s does not start with %s" % (src_page, DOCTYPE))
    if source.lstrip().startswith("---"):
        sys.exit("refusing to sync: %s has front matter; Jekyll would render it" % src_page)

    for name in VERBATIM:
        if not os.path.isfile(os.path.join(src_dir, name)):
            sys.exit("refusing to sync: %s is missing; the page needs it" % name)

    os.makedirs(dst_dir, exist_ok=True)
    changed = []

    # The page, with its header stamped on.
    dst_page = os.path.join(dst_dir, PAGE)
    body = body_of(source)
    old = None
    try:
        old = io.open(dst_page, encoding="utf-8").read()
    except IOError:
        pass
    if old is None or body_of(old) != body:
        io.open(dst_page, "w", encoding="utf-8").write(HEADER.format(date=date, sha=sha) + body)
        changed.append(PAGE)

    # Everything else, byte for byte.
    for name in VERBATIM:
        src, dst = os.path.join(src_dir, name), os.path.join(dst_dir, name)
        if read(src) != read(dst):
            shutil.copyfile(src, dst)
            changed.append(name)

    if changed:
        print("changed: %s" % ", ".join(changed))
    else:
        print("no change: the copy already matches the source")

    out = os.environ.get("GITHUB_OUTPUT")
    if out:
        with io.open(out, "a", encoding="utf-8") as fh:
            fh.write("changed=%s\n" % ("true" if changed else "false"))


if __name__ == "__main__":
    main()
